// The types of the API, from the versioned OpenAPI document (RFC-037 section 4.3).
//
// One function for both of its readers: `npm run api:types`, which writes
// `schema.d.ts`, and `npm test`, which checks that the file is what this
// produces. The two cannot drift apart, because there is one of them.

import openapiTS, { astToString } from "openapi-typescript";

export const OPENAPI = new URL("../src/api/openapi.json", import.meta.url);
export const SCHEMA_TYPES = new URL("../src/api/schema.d.ts", import.meta.url);

const HEADER =
  "// Generated by `npm run api:types` from openapi.json, which\n" +
  "// scripts/export_openapi.py writes from the API. Do not edit by hand.\n\n";

/** @returns {Promise<string>} the text of `schema.d.ts` */
export async function generateSchemaTypes() {
  const ast = await openapiTS(OPENAPI);
  return HEADER + astToString(ast);
}
